var i=`ci-cd-principles`;var n=91;var s={en:[{id:`T091-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`CI/CD Principles`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Continuous Integration merges and validates changes frequently; Continuous Delivery keeps releases deployable; Continuous Deployment automatically releases changes passing defined gates.`},{id:`B`,text:`Load balancing distributes requests or work across instances to improve utilization, capacity and availability.`},{id:`C`,text:`Blue-green deployment switches traffic between two complete environments; canary deployment gradually exposes a subset of traffic to a new version.`},{id:`D`,text:`An SLI is a quantitative service reliability indicator; an SLO is a target for that indicator; an SLA is a contractual commitment, often with consequences.`}]},{id:`T091-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`CI/CD Principles`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Instrument critical workflows with correlation IDs, structured logs, duration histograms, error rates and distributed spans.`},{id:`B`,text:`Build reproducibly, run fast quality gates first, protect branches and secrets, and promote the same verified artifact across environments.`},{id:`C`,text:`Define which failures to tolerate: instance crash, zone loss, timeout, bad data or dependency unavailability.`},{id:`D`,text:`Plan changes before applying them, use state and drift detection, separate environments, and keep secrets outside source.`}]},{id:`T091-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which practical project example best illustrates `},{t:`CI/CD Principles`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`A stateless Node.js API deploys from a pinned container image. If the new image fails, the orchestrator returns traffic to the previous verified image without editing hosts manually.`},{id:`B`,text:`A web API balances traffic across three replicas and drains a retiring instance before stopping it. Long WebSocket sessions may need different connection handling than short HTTP requests.`},{id:`C`,text:`An Angular frontend and Node.js API pipeline runs type checks, tests, build and integration tests, then deploys tagged artifacts through staging to production with health checks.`},{id:`D`,text:`A hotel SaaS can provision databases, networks and monitoring through reviewed IaC. Recreating staging becomes routine rather than relying on undocumented manual console clicks.`}]},{id:`T091-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`CI/CD Principles`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Redundant replicas sharing one database or cloud zone may share the same failure mode.`},{id:`B`,text:`IaC is not automatically idempotent or safe: changing a resource property may destroy state.`},{id:`C`,text:`A healthy process is not necessarily ready for traffic.`},{id:`D`,text:`A green pipeline does not guarantee a good release; it reflects the checks chosen.`}]},{id:`T091-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`The distinction is how production promotion occurs.`}]}]},{id:`T091-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Passing CI guarantees a release is safe without monitoring or rollback.`}]}]},{id:`T091-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Avoid building different artifacts in staging and production, and never give untrusted PR jobs production credentials.`}]}]},{id:`T091-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`CI/CD Principles`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Load balancing guarantees uniform response times regardless of backend health.`},{id:`B`,text:`Build reproducibly, run fast quality gates first, protect branches and secrets, and promote the same verified artifact across environments.`},{id:`C`,text:`Continuous Integration merges and validates changes frequently; Continuous Delivery keeps releases deployable; Continuous Deployment automatically releases changes passing defined gates.`},{id:`D`,text:`Deployment and release are necessarily one irreversible action.`}]},{id:`T091-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`CI/CD Principles`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Passing CI guarantees a release is safe without monitoring or rollback.`},{id:`B`,text:`A metric with no useful dimensions always identifies the root cause.`},{id:`C`,text:`Avoid building different artifacts in staging and production, and never give untrusted PR jobs production credentials.`},{id:`D`,text:`An Angular frontend and Node.js API pipeline runs type checks, tests, build and integration tests, then deploys tagged artifacts through staging to production with health checks.`}]},{id:`T091-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`An Angular frontend and Node.js API pipeline runs type checks, tests, build and integration tests, then deploys tagged artifacts through staging to production with health checks.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to configure a load-balancing design for HTTP and WebSocket traffic, specifying readiness, graceful shutdown, retries and uneven request costs.`},{id:`B`,text:`Ask an agent to model failures of mail, cache and database dependencies separately and define degraded behavior, recovery tests and observability.`},{id:`C`,text:`Ask an agent to design a CI/CD pipeline for a monorepo with caching, branch protection, artifact provenance, migrations and rollback on failed health checks.`},{id:`D`,text:`Ask an agent to draft isolated staging/production infrastructure with resource boundaries, encrypted state, access roles and a plan for destructive-change approval.`}]},{id:`T091-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`What evidence connects deployed bytes to reviewed source code and passed tests?`}]}]},{id:`T091-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`An Angular frontend and Node.js API pipeline runs type checks, tests, build and integration tests, then deploys tagged artifacts through staging to production with health checks.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`CI/CD Principles`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T091-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`An Angular frontend and Node.js API pipeline runs type checks, tests, build and integration tests, then deploys tagged artifacts through staging to production with health checks.`,b:!0},{t:` — propose three checks for `},{t:`CI/CD Principles`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T091-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`An Angular frontend and Node.js API pipeline runs type checks, tests, build and integration tests, then deploys tagged artifacts through staging to production with health checks.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T091-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`CI/CD Principles`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`An Angular frontend and Node.js API pipeline runs type checks, tests, build and integration tests, then deploys tagged artifacts through staging to production with health checks.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T091-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Принципи CI/CD`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Continuous Integration часто об’єднує та перевіряє зміни; Continuous Delivery підтримує готовність до релізу; Continuous Deployment автоматично випускає зміни після перевірок.`},{id:`B`,text:`Балансування розподіляє запити між інстансами задля кращого використання ресурсів, пропускної здатності та доступності.`},{id:`C`,text:`Blue-green перемикає трафік між двома середовищами; canary поступово спрямовує частину трафіку на нову версію.`},{id:`D`,text:`SLI — кількісний показник надійності; SLO — його цільове значення; SLA — договірне зобов’язання, часто із наслідками невиконання.`}]},{id:`T091-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Принципи CI/CD`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Інструментуйте важливі сценарії correlation ID, структурованими логами, гістограмами затримок, часткою помилок і distributed spans.`},{id:`B`,text:`Забезпечуйте відтворювані збірки, запускайте швидкі перевірки першими, захищайте гілки й секрети та просувайте один перевірений артефакт між середовищами.`},{id:`C`,text:`Визначте допустимі відмови: падіння інстансу, зони, timeout, некоректні дані чи недоступність залежності.`},{id:`D`,text:`Плануйте зміни до застосування, використовуйте state й пошук drift, ізолюйте середовища та тримайте секрети поза кодом.`}]},{id:`T091-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який приклад із практичного проєкту найкраще ілюструє `},{t:`Принципи CI/CD`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Stateless Node.js API розгортається з фіксованого контейнерного образу. Якщо нова версія не працює, оркестратор повертає трафік до попереднього образу без редагування серверів вручну.`},{id:`B`,text:`Веб-API розподіляє трафік між трьома репліками й дочікується завершення запитів перед зупинкою інстансу. Довгі WebSocket-з’єднання потребують іншої поведінки, ніж короткі HTTP.`},{id:`C`,text:`Pipeline Angular і Node.js запускає перевірку типів, тести, build та інтеграційні тести, потім просуває позначені артефакти через staging у production з health checks.`},{id:`D`,text:`Готельний SaaS може створювати БД, мережі й моніторинг через переглянутий IaC. Повторне розгортання staging стає звичайною процедурою замість ручних кліків у консолі.`}]},{id:`T091-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Принципи CI/CD`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Резервні репліки зі спільною БД чи зоною хмари можуть мати спільну точку відмови.`},{id:`B`,text:`IaC не є автоматично безпечним чи ідемпотентним: зміна властивості може знищити ресурс із даними.`},{id:`C`,text:`Живий процес не обов’язково готовий до трафіку.`},{id:`D`,text:`Зелений pipeline не гарантує добрий реліз — лише виконання вибраних перевірок.`}]},{id:`T091-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Різниця — у способі потрапляння в production.`}]}]},{id:`T091-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Успішний CI гарантує безпечний реліз без моніторингу чи відкату.`}]}]},{id:`T091-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Не збирайте різні артефакти для staging і production та не надавайте неперевіреним PR production-креденшали.`}]}]},{id:`T091-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Принципи CI/CD`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Балансування гарантує однаковий час відповіді незалежно від стану бекендів.`},{id:`B`,text:`Забезпечуйте відтворювані збірки, запускайте швидкі перевірки першими, захищайте гілки й секрети та просувайте один перевірений артефакт між середовищами.`},{id:`C`,text:`Continuous Integration часто об’єднує та перевіряє зміни; Continuous Delivery підтримує готовність до релізу; Continuous Deployment автоматично випускає зміни після перевірок.`},{id:`D`,text:`Розгортання та випуск функції обов’язково одна незворотна дія.`}]},{id:`T091-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Принципи CI/CD`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Успішний CI гарантує безпечний реліз без моніторингу чи відкату.`},{id:`B`,text:`Метрика без корисних вимірів завжди визначає першопричину збою.`},{id:`C`,text:`Не збирайте різні артефакти для staging і production та не надавайте неперевіреним PR production-креденшали.`},{id:`D`,text:`Pipeline Angular і Node.js запускає перевірку типів, тести, build та інтеграційні тести, потім просуває позначені артефакти через staging у production з health checks.`}]},{id:`T091-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Pipeline Angular і Node.js запускає перевірку типів, тести, build та інтеграційні тести, потім просуває позначені артефакти через staging у production з health checks.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента спроєктувати балансування HTTP та WebSocket, визначити readiness, graceful shutdown, повтори та нерівну ціну запитів.`},{id:`B`,text:`Попросіть агента окремо змоделювати збої пошти, кешу й БД та визначити деградацію, тести відновлення й моніторинг.`},{id:`C`,text:`Попросіть агента спроєктувати CI/CD монорепозиторію з кешем, захистом гілок, походженням артефактів, міграціями й відкатом після health-check збою.`},{id:`D`,text:`Попросіть агента описати ізольовану інфраструктуру staging/production із межами ресурсів, шифрованим state, ролями та затвердженням небезпечних змін.`}]},{id:`T091-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Які докази пов’язують розгорнуті байти з перевіреним кодом і тестами?`}]}]},{id:`T091-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Pipeline Angular і Node.js запускає перевірку типів, тести, build та інтеграційні тести, потім просуває позначені артефакти через staging у production з health checks.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Принципи CI/CD`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T091-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Pipeline Angular і Node.js запускає перевірку типів, тести, build та інтеграційні тести, потім просуває позначені артефакти через staging у production з health checks.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Принципи CI/CD`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T091-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Pipeline Angular і Node.js запускає перевірку типів, тести, build та інтеграційні тести, потім просуває позначені артефакти через staging у production з health checks.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T091-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Принципи CI/CD`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Pipeline Angular і Node.js запускає перевірку типів, тести, build та інтеграційні тести, потім просуває позначені артефакти через staging у production з health checks.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var o={slug:i,topicId:91,questions:s};export{o as default,s as questions,i as slug,n as topicId};